import sys
import re
import subprocess
import os

def parse_input():
    template = sys.stdin.readline().strip()
    variables = {}
    for line in sys.stdin:
        line = line.strip()
        if line:
            name, value = line.split('=', 1)
            variables[name] = int(value)
    return template, variables

def evaluate_expression(expr, variables):
    try:
        # Replace variable names with their values and evaluate
        for name in variables:
            expr = expr.replace(name, str(variables[name]))
        result = eval(expr)
        return result
    except Exception as e:
        raise ValueError(f"expression {expr}")

def replace_placeholders(template, variables):
    placeholders = re.findall(r'\{\{([^}]+)\}\}', template)
    for expr in placeholders:
        try:
            value = evaluate_expression(expr, variables)
            template = template.replace(f'{{{{{expr}}}}}', str(value))
        except ValueError as e:
            print(f"ERROR: expression {expr}", file=sys.stderr)
            sys.exit(1)
    return template

def run_command(command):
    try:
        result = subprocess.run(command, shell=True, check=True, text=True, capture_output=True)
        return 0, result.stdout
    except subprocess.CalledProcessError as e:
        return e.returncode, e.output

def main():
    template, variables = parse_input()
    final_command = replace_placeholders(template, variables)
    exit_code, _ = run_command(final_command)

    with open('runner.log', 'a') as log_file:
        log_file.write(f'RUN {final_command} exit {exit_code}\n')

    if exit_code == 0:
        sys.exit(0)
    else:
        print(f"ERROR: exit {exit_code}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
